public class Main {
    // Base case: n <= 1 is answered directly. Recursive case: n shrinks by 1.
    // Time O(n), space O(n) stack frames.
    static long fact(int n) {
        if (n <= 1) return 1;          // base case stops the recursion
        return n * fact(n - 1);        // smaller input, then combine
    }

    // Steps by 2 toward the base case n == 1. An even n jumps over it.
    // The depth guard stands in for the stack overflow a real run would hit.
    static String countDown(int n, int depth) {
        if (n == 1) return "reached the base case after " + depth + " calls";
        if (depth == 50) return "missed the base case, guard stopped it after " + depth + " calls (n = " + n + ")";
        return countDown(n - 2, depth + 1);
    }

    public static void main(String[] args) {
        for (int n = 0; n <= 5; n++) System.out.println("fact(" + n + ") = " + fact(n));
        System.out.println("countDown(7): " + countDown(7, 1));
        System.out.println("countDown(6): " + countDown(6, 1));
    }
}

