public class Main {
    static long calls = 0;
    static int depth = 0, maxDepth = 0;

    // Naive fib. Time O(1.6^n) calls, space O(n): only one root-to-leaf chain is alive at once.
    static long fib(int n) {
        calls++;
        depth++;                               // a frame is pushed
        if (depth > maxDepth) maxDepth = depth;
        long result = (n <= 1) ? n : fib(n - 1) + fib(n - 2);
        depth--;                               // the frame is popped on return
        return result;
    }

    public static void main(String[] args) {
        int[] inputs = {5, 10, 20, 25};
        for (int n : inputs) {
            calls = 0; depth = 0; maxDepth = 0;
            long value = fib(n);
            // Calls explode, but the stack never holds more than n frames.
            System.out.println("fib(" + n + ") = " + value + ", calls = " + calls
                    + ", deepest stack = " + maxDepth + " frames");
        }
    }
}

