import java.util.*;

public class Main {
    static int[][] adj = {{1, 2}, {3, 4}, {5}, {}, {5}, {}};

    // Recursive DFS: the call stack remembers where to go back to.
    static void dfs(int v, boolean[] seen, StringBuilder order) {
        seen[v] = true;
        order.append(v).append(' ');
        for (int w : adj[v]) if (!seen[w]) dfs(w, seen, order);
    }

    // Same visit order with our own stack on the heap. Time O(V + E), space O(V + E).
    static String dfsIterative(int start) {
        boolean[] seen = new boolean[adj.length];
        StringBuilder order = new StringBuilder();
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(start);
        while (!stack.isEmpty()) {
            int v = stack.pop();
            if (seen[v]) continue;              // pushed twice, visit once
            seen[v] = true;
            order.append(v).append(' ');
            // Push neighbours in reverse so the first neighbour is popped first.
            for (int i = adj[v].length - 1; i >= 0; i--) if (!seen[adj[v][i]]) stack.push(adj[v][i]);
        }
        return order.toString().trim();
    }

    public static void main(String[] args) {
        System.out.println("graph: 0->[1,2] 1->[3,4] 2->[5] 3->[] 4->[5] 5->[]");
        StringBuilder order = new StringBuilder();
        dfs(0, new boolean[adj.length], order);
        System.out.println("recursive order: " + order.toString().trim());
        System.out.println("iterative order: " + dfsIterative(0));

        // A chain 0 -> 1 -> ... of 1,000,000 nodes would overflow the call stack
        // if walked recursively. The explicit stack handles it without trouble.
        int n = 1000000, visited = 0;
        Deque<Integer> stack = new ArrayDeque<>();
        stack.push(0);
        while (!stack.isEmpty()) {
            int v = stack.pop();
            visited++;
            if (v + 1 < n) stack.push(v + 1);
        }
        System.out.println("chain of " + n + " nodes, visited with explicit stack: " + visited);
    }
}

