#include <bits/stdc++.h>
using namespace std;

vector<vector<int>> adj = {{1, 2}, {3, 4}, {5}, {}, {5}, {}};

// Recursive DFS: the call stack remembers where to go back to.
void dfs(int v, vector<bool>& seen, string& order) {
    seen[v] = true;
    order += to_string(v) + " ";
    for (int w : adj[v]) if (!seen[w]) dfs(w, seen, order);
}

// Same visit order with our own stack on the heap. Time O(V + E), space O(V + E).
string dfsIterative(int start) {
    vector<bool> seen(adj.size(), false);
    string order;
    vector<int> st = {start};
    while (!st.empty()) {
        int v = st.back(); st.pop_back();
        if (seen[v]) continue;              // pushed twice, visit once
        seen[v] = true;
        order += to_string(v) + " ";
        // Push neighbours in reverse so the first neighbour is popped first.
        for (int i = (int)adj[v].size() - 1; i >= 0; i--) if (!seen[adj[v][i]]) st.push_back(adj[v][i]);
    }
    order.pop_back();
    return order;
}

int main() {
    cout << "graph: 0->[1,2] 1->[3,4] 2->[5] 3->[] 4->[5] 5->[]\n";
    vector<bool> seen(adj.size(), false);
    string order;
    dfs(0, seen, order);
    order.pop_back();
    cout << "recursive order: " << order << "\n";
    cout << "iterative order: " << dfsIterative(0) << "\n";

    // A chain 0 -> 1 -> ... of 1,000,000 nodes would overflow the call stack
    // if walked recursively. The explicit stack handles it without trouble.
    int n = 1000000, visited = 0;
    vector<int> st = {0};
    while (!st.empty()) {
        int v = st.back(); st.pop_back();
        visited++;
        if (v + 1 < n) st.push_back(v + 1);
    }
    cout << "chain of " << n << " nodes, visited with explicit stack: " << visited << "\n";
    return 0;
}

