        order.Append(v).Append(' ');
        foreach (int w in adj[v]) if (!seen[w]) Dfs(w, seen, order);
    }

    // Same visit order with our own stack on the heap. Time O(V + E), space O(V + E).
    static string DfsIterative(int start) {
        bool[] seen = new bool[adj.Length];
        StringBuilder order = new StringBuilder();
        Stack<int> stack = new Stack<int>();
        stack.Push(start);
        while (stack.Count > 0) {
            int v = stack.Pop();
            if (seen[v]) continue;              // pushed twice, visit once
            seen[v] = true;
            order.Append(v).Append(' ');
            // Push neighbours in reverse so the first neighbour is popped first.
            for (int i = adj[v].Length - 1; i >= 0; i--) if (!seen[adj[v][i]]) stack.Push(adj[v][i]);
        }
        return order.ToString().Trim();
    }

    static void Main() {
        Console.WriteLine("graph: 0->[1,2] 1->[3,4] 2->[5] 3->[] 4->[5] 5->[]");
        StringBuilder order = new StringBuilder();
        Dfs(0, new bool[adj.Length], order);
        Console.WriteLine("recursive order: " + order.ToString().Trim());
        Console.WriteLine("iterative order: " + DfsIterative(0));

        // A chain 0 -> 1 -> ... of 1,000,000 nodes would overflow the call stack
        // if walked recursively. The explicit stack handles it without trouble.
        int n = 1000000, visited = 0;
        Stack<int> st = new Stack<int>();
        st.Push(0);
        while (st.Count > 0) {
            int v = st.Pop();
            visited++;
            if (v + 1 < n) st.Push(v + 1);
        }
        Console.WriteLine("chain of " + n + " nodes, visited with explicit stack: " + visited);
    }
}

