public class Main {
    // T(n) = T(n/2) + 1  ->  O(log n). Returns the number of calls.
    static long halve(int n) {
        if (n <= 1) return 1;
        return 1 + halve(n / 2);
    }

    // T(n) = 2T(n/2) + n  ->  O(n log n). Returns the total work done.
    static long splitAndMerge(int n) {
        if (n <= 1) return 1;
        return splitAndMerge(n / 2) + splitAndMerge(n / 2) + n;   // n = work outside the calls
    }

    // T(n) = 2T(n-1) + 1  ->  O(2^n). Returns the number of calls.
    static long twoBranches(int n) {
        if (n == 0) return 1;
        return 1 + twoBranches(n - 1) + twoBranches(n - 1);
    }

    // T(n) = n * T(n-1) + 1  ->  O(n!). Returns the number of calls.
    static long nBranches(int n) {
        long total = 1;
        for (int i = 0; i < n; i++) total += nBranches(n - 1);   // n choices at this level
        return total;
    }

    public static void main(String[] args) {
        // Each line: the recurrence, the input size, and the measured amount of work.
        System.out.println("T(n) = T(n/2) + 1,   n = 1024: " + halve(1024) + " calls");
        System.out.println("T(n) = 2T(n/2) + n,  n = 1024: " + splitAndMerge(1024) + " units of work");
        System.out.println("T(n) = 2T(n-1) + 1,  n = 16:   " + twoBranches(16) + " calls");
        System.out.println("T(n) = n*T(n-1) + 1, n = 8:    " + nBranches(8) + " calls");
    }
}

