public class Main {
    static long moves = 0;

    // Move n disks from 'from' to 'to' using 'via' as the spare peg.
    // Time O(2^n) moves, space O(n) stack frames.
    static void hanoi(int n, char from, char to, char via, boolean print) {
        if (n == 0) return;                          // base case: nothing to move
        hanoi(n - 1, from, via, to, print);          // clear the n-1 smaller disks out of the way
        moves++;
        if (print) System.out.println("  move disk " + n + ": " + from + " -> " + to);
        hanoi(n - 1, via, to, from, print);          // put the smaller disks back on top
    }

