        System.out.println("3 disks, from A to C:");
        hanoi(3, 'A', 'C', 'B', true);
        System.out.println("moves used: " + moves);

        // The count follows M(n) = 2M(n-1) + 1 = 2^n - 1.
        for (int n = 1; n <= 10; n++) {
