import java.util.*;
import java.util.stream.*;

public class Main {
    static int[] a = {2, 3, 5, 7, 8, 10, 11, 13, 14, 17, 19, 20};   // sorted, all positive
    static int nodes = 0;
    static List<Integer> cur = new ArrayList<>();
    static List<String> found = new ArrayList<>();

    // Backtracking: the partial sum is checked at every step, so hopeless branches are never entered.
    // Worst case O(2^n) time, O(n) stack.
    static void search(int start, int remaining) {
        nodes++;
        if (remaining == 0) {
            found.add(cur.stream().map(String::valueOf).collect(Collectors.joining("+")));
            return;
        }
        for (int j = start; j < a.length; j++) {
            if (a[j] > remaining) break;          // prune: sorted, so every later value is too big too
            cur.add(a[j]);                        // choose
            search(j + 1, remaining - a[j]);      // explore
            cur.remove(cur.size() - 1);           // un-choose
        }
    }

    public static void main(String[] args) {
        int target = 21, n = a.length, hits = 0;
        // Brute force: build every complete subset and test it only at the end. O(n * 2^n).
        for (int mask = 0; mask < (1 << n); mask++) {
            int sum = 0;
            for (int i = 0; i < n; i++) if ((mask & (1 << i)) != 0) sum += a[i];
            if (sum == target) hits++;
        }
        search(0, target);
        System.out.println("numbers: " + Arrays.toString(a).replace(" ", "") + ", target: " + target);
        System.out.println("brute force: " + (1 << n) + " subsets built, " + hits + " hit the target");
        System.out.println("backtracking: " + nodes + " nodes visited, " + found.size() + " hit the target");
        for (String s : found) System.out.println("  " + s);
    }
}

