import java.util.*;

public class Main {
    // Lists every subset of the sorted array a. Time O(n * 2^n), space O(n) stack.
    static void gen(int[] a, int start, List<Integer> cur, List<String> out, boolean skipDuplicates) {
        out.add(cur.toString().replace(" ", ""));      // every node of the tree is one subset
        for (int j = start; j < a.length; j++) {
            // At one level, only the first copy of a value may start a branch.
            if (skipDuplicates && j > start && a[j] == a[j - 1]) continue;
            cur.add(a[j]);                             // choose
            gen(a, j + 1, cur, out, skipDuplicates);   // explore
            cur.remove(cur.size() - 1);                // un-choose
        }
    }

    public static void main(String[] args) {
        int[] a = {2, 1, 2};
        System.out.println("input: " + Arrays.toString(a).replace(" ", ""));
        Arrays.sort(a);                                // equal values become neighbours
        System.out.println("sorted: " + Arrays.toString(a).replace(" ", ""));

        List<String> plain = new ArrayList<>();
        gen(a, 0, new ArrayList<>(), plain, false);
        System.out.println("without the skip: " + plain.size() + " subsets: " + String.join(" ", plain));

        List<String> unique = new ArrayList<>();
        gen(a, 0, new ArrayList<>(), unique, true);
        System.out.println("with the skip:    " + unique.size() + " subsets: " + String.join(" ", unique));
    }
}

