import java.util.*;

public class Main {
    // Swap method: the array itself is the state. Position i gets each remaining element in turn.
    static void bySwap(int[] a, int i, List<String> out) {
        if (i == a.length) { out.add(Arrays.toString(a).replace(" ", "")); return; }
        for (int j = i; j < a.length; j++) {
            int t = a[i]; a[i] = a[j]; a[j] = t;     // choose: bring a[j] to position i
            bySwap(a, i + 1, out);                   // explore
            t = a[i]; a[i] = a[j]; a[j] = t;         // un-choose: swap back
        }
    }

    // used[] method: build a separate list, mark what is already in it. O(n) extra memory.
    static void byUsed(int[] a, boolean[] used, List<Integer> cur, List<String> out) {
        if (cur.size() == a.length) { out.add(cur.toString().replace(" ", "")); return; }
        for (int i = 0; i < a.length; i++) {
            if (used[i]) continue;
            used[i] = true; cur.add(a[i]);           // choose
            byUsed(a, used, cur, out);               // explore
            used[i] = false; cur.remove(cur.size() - 1);   // un-choose
        }
    }

    public static void main(String[] args) {
        int[] a = {1, 2, 3};
        System.out.println("input: " + Arrays.toString(a).replace(" ", ""));
        // Both are O(n * n!) time. Only used[] gives sorted (lexicographic) order.
        List<String> swapOrder = new ArrayList<>(), usedOrder = new ArrayList<>();
        bySwap(a, 0, swapOrder);
        byUsed(a, new boolean[a.length], new ArrayList<>(), usedOrder);
        System.out.println("swap:   " + String.join(" ", swapOrder));
        System.out.println("used[]: " + String.join(" ", usedOrder));
        System.out.println("array after swap method (restored): " + Arrays.toString(a).replace(" ", ""));
    }
}

