public class Main {
    static int[] g = new int[81], row = new int[9], col = new int[9], box = new int[9];
    static int tries = 0;

    // Put digit d into cell p, or take it out again: flip its bit in three masks.
    static void flip(int p, int d) {
        int r = p / 9, c = p % 9, bit = 1 << d;
        row[r] ^= bit; col[c] ^= bit; box[(r / 3) * 3 + c / 3] ^= bit;
    }

    // Exponential in the worst case, fast in practice; space O(81) stack frames.
    static boolean solve(int p) {
        while (p < 81 && g[p] != 0) p++;              // next empty cell
        if (p == 81) return true;                     // goal: nothing left to fill
        int r = p / 9, c = p % 9;
        int used = row[r] | col[c] | box[(r / 3) * 3 + c / 3];
        for (int d = 1; d <= 9; d++) {
            if ((used & (1 << d)) != 0) continue;     // O(1) validity check
            tries++;
            g[p] = d; flip(p, d);                     // choose
            if (solve(p + 1)) return true;            // explore; keep the grid on success
            g[p] = 0; flip(p, d);                     // un-choose
        }
        return false;                                 // no digit fits: the caller must change
    }

    public static void main(String[] args) {
        String s = "530070000600195000098000060800060003400803001700020006060000280000419005000080079";
        for (int p = 0; p < 81; p++) {
            g[p] = s.charAt(p) - '0';
            if (g[p] != 0) flip(p, g[p]);
        }
        System.out.println("puzzle (0 = empty): " + s);
        boolean ok = solve(0);
        System.out.println("solved: " + (ok ? "yes" : "no") + ", digits tried: " + tries);
        for (int r = 0; r < 9; r++) {
            StringBuilder line = new StringBuilder();
            for (int c = 0; c < 9; c++) line.append(g[r * 9 + c]);
            System.out.println(line);
        }
    }
}

