public class Main {
    static final long BUDGET = 100000000L;   // about 10^8 simple steps per second

    static long pow2(int n) {                // size of a subset tree
        long r = 1;
        for (int i = 0; i < n; i++) r *= 2;
        return r;
    }

    static long factorial(int n) {           // size of a permutation tree
        long r = 1;
        for (int i = 2; i <= n; i++) r *= i;
        return r;
    }

    static String verdict(long size) {
        return size <= BUDGET ? "fits in the budget" : "too slow, look for pruning or DP";
    }

    public static void main(String[] args) {
        // Each estimate is O(n) to compute; the point is to do it before writing code.
        System.out.println("budget: " + BUDGET + " steps");
        int[] subsetSizes = {10, 20, 25, 30, 40};
        for (int n : subsetSizes)
            System.out.println("subsets,      n = " + n + ": 2^n = " + pow2(n) + " -> " + verdict(pow2(n)));
        int[] permSizes = {8, 10, 11, 12, 15};
        for (int n : permSizes)
            System.out.println("permutations, n = " + n + ": n! = " + factorial(n) + " -> " + verdict(factorial(n)));
        // Meet in the middle for n = 40: two halves of 2^20 each.
        System.out.println("n = 40 split in two halves: 2 * 2^20 = " + 2 * pow2(20) + " -> " + verdict(2 * pow2(20)));
    }
}

