import java.util.*;

public class Main {
    // Generates all subsets of a. Time O(n * 2^n), space O(n) stack plus the output.
    static void gen(int[] a, int start, List<Integer> cur, List<List<Integer>> out, boolean copy) {
        if (copy) out.add(new ArrayList<>(cur));   // correct: a snapshot of cur as it is now
        else out.add(cur);                         // bug: every entry is the same list object
        for (int j = start; j < a.length; j++) {
            cur.add(a[j]);                         // choose
            gen(a, j + 1, cur, out, copy);         // explore
            cur.remove(cur.size() - 1);            // un-choose: this also empties the saved references
        }
    }

    static String show(List<List<Integer>> out) {
        StringBuilder sb = new StringBuilder();
        for (List<Integer> s : out) sb.append(s.toString().replace(" ", "")).append(' ');
        return sb.toString().trim();
    }

    public static void main(String[] args) {
        int[] a = {1, 2, 3};
        System.out.println("input: " + Arrays.toString(a).replace(" ", ""));

        List<List<Integer>> buggy = new ArrayList<>();
        gen(a, 0, new ArrayList<>(), buggy, false);
        // All 8 entries point at one list, which is empty again when the search ends.
        System.out.println("saving the reference: " + show(buggy));

        List<List<Integer>> correct = new ArrayList<>();
        gen(a, 0, new ArrayList<>(), correct, true);
        System.out.println("saving a copy:        " + show(correct));
    }
}

