#include <bits/stdc++.h>
using namespace std;

string show(const vector<int>& v) {
    string s = "[";
    for (size_t i = 0; i < v.size(); i++) s += (i ? "," : "") + to_string(v[i]);
    return s + "]";
}

// Generates all subsets of a. Time O(n * 2^n), space O(n) stack plus the output.
// C++ copies a vector by default, so the bug only appears if you store pointers.
void gen(const vector<int>& a, int start, vector<int>& cur,
         vector<vector<int>*>& refs, vector<vector<int>>& copies) {
    refs.push_back(&cur);                  // bug: every entry is the address of the same vector
    copies.push_back(cur);                 // correct: a snapshot of cur as it is now
    for (int j = start; j < (int)a.size(); j++) {
        cur.push_back(a[j]);               // choose
        gen(a, j + 1, cur, refs, copies);  // explore
        cur.pop_back();                    // un-choose: this also empties what the pointers see
    }
}

int main() {
    vector<int> a = {1, 2, 3}, cur;
    cout << "input: " << show(a) << "\n";

    vector<vector<int>*> refs;
    vector<vector<int>> copies;
    gen(a, 0, cur, refs, copies);
    // All 8 pointers lead to one vector, which is empty again when the search ends.
    cout << "saving the reference:";
    for (vector<int>* p : refs) cout << " " << show(*p);
    cout << "\nsaving a copy:       ";
    for (const vector<int>& s : copies) cout << " " << show(s);
    cout << "\n";
    return 0;
}

