import java.util.*;

public class Main {
    static int[] a = new int[18];
    static long plainCalls = 0, memoCalls = 0;
    static long[][] memo;

    // Plain backtracking: skip a[i] or take it. Time O(2^n), space O(n).
    static long plain(int i, int remaining) {
        plainCalls++;
        if (i == a.length) return remaining == 0 ? 1 : 0;
        long ways = plain(i + 1, remaining);                          // skip a[i]
        if (a[i] <= remaining) ways += plain(i + 1, remaining - a[i]);   // take a[i]
        return ways;
    }

    // Same recursion, but the answer depends only on (i, remaining), so store it.
    // Time O(n * target), space O(n * target).
