import java.util.*;

public class Main {
    // Solution under test. With buggy = true it uses the wrong skip rule (j > 0).
    static void gen(int[] a, int start, String cur, List<String> out, boolean buggy) {
        out.add(cur);
        for (int j = start; j < a.length; j++) {
            int floor = buggy ? 0 : start;
            if (j > floor && a[j] == a[j - 1]) continue;
            gen(a, j + 1, cur + a[j] + ",", out, buggy);
        }
    }

    // Reference: try all 2^n masks and let a set remove duplicates. Slow but obviously right.
    static Set<String> brute(int[] a) {
        Set<String> all = new HashSet<>();
        for (int mask = 0; mask < (1 << a.length); mask++) {
            String key = "";
            for (int i = 0; i < a.length; i++) if ((mask & (1 << i)) != 0) key += a[i] + ",";
            all.add(key);
        }
        return all;
    }

    // Same count, no repeats, and every answer is in the reference.
    static boolean agrees(int[] a, boolean buggy) {
        List<String> out = new ArrayList<>();
        gen(a, 0, "", out, buggy);
        Set<String> ref = brute(a);
        return out.size() == ref.size() && new HashSet<>(out).size() == out.size() && ref.containsAll(out);
    }

    public static void main(String[] args) {
        int seed = 1, badCorrect = 0, badBuggy = 0;
        String firstFail = "";
        for (int t = 0; t < 200; t++) {
            seed = (seed * 75 + 74) % 65537;            // tiny repeatable random generator
            int[] a = new int[1 + seed % 5];
            for (int i = 0; i < a.length; i++) { seed = (seed * 75 + 74) % 65537; a[i] = 1 + seed % 3; }
            Arrays.sort(a);
            if (!agrees(a, false)) badCorrect++;
            if (!agrees(a, true)) {
                if (badBuggy == 0) firstFail = Arrays.toString(a).replace(" ", "");
                badBuggy++;
            }
        }
        // Each test costs O(n * 2^n) with n <= 5, so 200 tests run instantly.
        System.out.println("200 random sorted inputs, length 1 to 5, values 1 to 3");
        System.out.println("rule j > start: " + badCorrect + " mismatches");
        System.out.println("rule j > 0:     " + badBuggy + " mismatches, first failing input " + firstFail);
    }
}

